<div class="table-responsive"><table class="student-table"><thead><tr><th>Mahasiswa</th><th>NIM</th><th>Email</th><th>Jurusan</th><th>Jenis kelamin</th><?php if ($showActions): ?><th>Aksi</th><?php endif ?></tr></thead><tbody>
<?php foreach ($mahasiswa as $row): ?><tr><td><div class="student-name"><?php if ($row['foto']): ?><img class="avatar" src="<?= site_url('mahasiswa/' . $row['id'] . '/photo') ?>" alt="Foto <?= esc($row['nama'], 'attr') ?>"><?php else: ?><span class="avatar avatar-fallback"><?= esc(mb_strtoupper(mb_substr($row['nama'], 0, 1))) ?></span><?php endif ?><strong><?= esc($row['nama']) ?></strong></div></td><td><?= esc($row['nim']) ?></td><td><?= esc($row['email']) ?></td><td><span class="department"><?= esc($row['jurusan']) ?></span></td><td><?= esc($row['jenis_kelamin']) ?></td><?php if ($showActions): ?><td class="actions"><a href="<?= site_url('mahasiswa/' . $row['id'] . '/edit') ?>">Edit</a><form method="post" action="<?= site_url('mahasiswa/' . $row['id'] . '/delete') ?>" onsubmit="return confirm('Hapus data mahasiswa ini beserta fotonya?')"><?= csrf_field() ?><button type="submit">Hapus</button></form></td><?php endif ?></tr><?php endforeach ?>
<?php if (! $mahasiswa): ?><tr><td colspan="<?= $showActions ? 6 : 5 ?>" class="empty-state">Belum ada data mahasiswa. <a href="<?= site_url('mahasiswa/create') ?>">Tambah mahasiswa</a> untuk memulai.</td></tr><?php endif ?>
</tbody></table></div>
